{"task":{"id":"Probe203_typed_toggle","spec":"A typed toggle state machine with synchronous reset. rst selects CALM (code 1); each step toggles CALM (code 1) and ARMED (code 6), otherwise hold. flag is high exactly for ARMED. Retain the command_t enum interpretation for alias_state and keep all public ports one bit.","interface":{"top":"TopModule","ports":[{"name":"clk","direction":"input","width":1,"signed":false},{"name":"rst","direction":"input","width":1,"signed":false},{"name":"step","direction":"input","width":1,"signed":false},{"name":"flag","direction":"output","width":1,"signed":false}]},"constraints":"SystemVerilog, exactly one self-contained TopModule DUT. Inline all helper logic inside TopModule; do not define auxiliary modules. xczu3eg-sbva484-1-e; 5 ns synthesis clock; simulator seed 1. No reference dependencies, hierarchy outside the DUT, file access, includes or DPI."},"current":{"revision_id":"72408bbd-5744-44dd-9b8b-15545de4bf25","source_sha256":"2306bcc3cb019fe9f9d7c728e196e242818900152db82a6364fd4c7ed9c82a69","source":"module TopModule(input clk,input rst,input step,output flag);
typedef enum logic [2:0] {CALM=3'd1,ARMED=3'd6} command_t;
command_t alias_state;
logic [2:0] stored_state;
always @(posedge clk) if(rst) stored_state<=CALM; else if(step) stored_state<=(stored_state==CALM)?ARMED:CALM;
assign alias_state=stored_state;
assign flag=(alias_state==ARMED);
endmodule
